449: /// `#terminal=ls;neofetch`, `#photos`, `#photo` / `#photo=edit` / `#photo=info`, `#menu` — open the suite in a given state
450: /// (handy for sharing a view and for automated screenshots).
451: #[cfg(target_arch = "wasm32")]
452: fn deep_link(a: &mut SmartApp) {
453:     use crate::shell::AppId;
454:     let h = web_sys::window().and_then(|w| w.location().hash().ok()).unwrap_or_default();
455:     let h = h.trim_start_matches('#');
456:     let (name, arg) = h.split_once('=').unwrap_or((h, ""));
457:     match name {
458:         "terminal" => {
459:             a.open_app(AppId::Terminal);
460:             a.shell.term.command("new");
461:             for c in arg.split(';').filter(|c| !c.is_empty()) {
462:                 a.term_submit(0, c.replace("%20", " "));
463:             }
464:         }
465:         "photos" => a.open_app(AppId::Photos),
466:         "top" => {
467:             a.open_app(AppId::Terminal);
468:             a.shell.term.command("new");
469:             a.term_submit(0, "top".into());
470:         }
471:         "palette" => {
472:             match arg {
473:                 "photos" => a.open_app(AppId::Photos),
474:                 "terminal" => a.open_app(AppId::Terminal),
475:                 _ => {}
476:             }
477:             a.act(Act::Palette);
478:         }
479:         "settings" => {
480:             let app = if arg == "terminal" { AppId::Terminal } else { AppId::Photos };
481:             a.open_app(app);
482:             a.shell.settings = Some((app, 0));
483:         }
484:         "photomenu" => {
485:             a.open_app(AppId::Photos);
486:             if arg == "viewer" {
487:                 if let Some(l) = a.photos_first() {
488:                     a.photos_show(l);
489:                 }
490:                 let items = a.photos_viewer_menu();
491:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
492:             } else {
493:                 let items = a.photos_library_menu();
494:                 a.open_app_menu(egui::pos2(760.0, 300.0), items);
495:             }
496:         }
497:         "termmenu" => {
498:             a.open_app(AppId::Terminal);
499:             a.shell.term.command("new");
500:             a.term_submit(0, "ls".into());
501:             let items = a.term_menu_main();
502:             a.open_app_menu(egui::pos2(900.0, 300.0), items);
503:         }
504:         "photo" => {
505:             a.open_app(AppId::Photos);
506:             let first = a.photos_first();
507:             if let Some(l) = first {
508:                 a.photos_show(l);
509:             }
510:             a.shell.photos.edit = arg == "edit";
511:             a.shell.photos.info = arg == "info";
512:             if arg == "edit" {
513:                 a.shell.photos.adj = crate::photos::Adjust { exposure: 0.1, contrast: 0.25, saturation: 0.3, warmth: 0.3, vignette: 0.4 };
514:                 a.shell.photos.dirty = true;
515:             }
516:         }
517:         "copy" => {
518:             // Copies the first regular file found under Home to Downloads — a real transfer demo.
519:             let mut stack = vec![a.be.home()];
520:             let mut found = None;
521:             while let Some(d) = stack.pop() {
522:                 if let Some(fs) = a.be.registry.get(&d.fs) {
523:                     if let Ok(l) = fs.list(&d.path) {
524:                         for e in l {
525:                             if !e.is_dir {
