187: /// Parsed command line. `argv` excludes the program name.
188: #[derive(Clone, Debug, PartialEq, Eq)]
189: pub enum ArgsOutcome {
190:     Help,
191:     Version,
192:     Scan { roots: Vec<String> },
193:     Smoke { roots: Vec<String> },
194:     Run { roots: Vec<String> },
195:     Error(String),
196: }
197: 
198: /// Parse CLI args (excludes argv[0]). `--scan`/`--smoke` select the headless
199: /// mode; anything else (or nothing) selects the window. Empty roots in
200: /// Scan/Smoke/Run resolve to [`default_roots`].
201: pub fn parse_args(argv: &[String]) -> ArgsOutcome {
202:     let mut roots: Vec<String> = Vec::new();
203:     let mut mode_scan = false;
204:     let mut mode_smoke = false;
205:     let mut i = 0usize;
206:     while i < argv.len() {
207:         let a = &argv[i];
208:         match a.as_str() {
209:             "--" => {
210:                 for rest in &argv[i + 1..] {
211:                     roots.push(rest.clone());
212:                 }
213:                 break;
214:             }
215:             "-h" | "--help" | "help" => return ArgsOutcome::Help,
216:             "-V" | "--version" | "version" => return ArgsOutcome::Version,
217:             "--scan" => mode_scan = true,
218:             "--smoke" => mode_smoke = true,
219:             "--dir" => {
220:                 let Some(d) = argv.get(i + 1) else {
221:                     return ArgsOutcome::Error("--dir needs a directory argument".into());
222:                 };
223:                 roots.push(d.clone());
224:                 i += 1;
225:             }
226:             s if s.starts_with("--dir=") => {
227:                 let d = s.trim_start_matches("--dir=");
228:                 if d.is_empty() {
229:                     return ArgsOutcome::Error("--dir= needs a directory".into());
230:                 }
231:                 roots.push(d.to_string());
232:             }
233:             s if s.starts_with('-') && s != "-" => {
234:                 return ArgsOutcome::Error(format!("unknown option: {s} (try --help)"));
235:             }
236:             _ => roots.push(a.clone()),
237:         }
238:         i += 1;
239:     }
240:     if mode_scan && mode_smoke {
241:         return ArgsOutcome::Error("--scan and --smoke are mutually exclusive".into());
242:     }
243:     let roots = if roots.is_empty() { default_roots() } else { roots };
244:     if mode_scan {
245:         ArgsOutcome::Scan { roots }
246:     } else if mode_smoke {
247:         ArgsOutcome::Smoke { roots }
248:     } else {
249:         ArgsOutcome::Run { roots }
250:     }
251: }
252: 
253: /// Default library roots: Pictures when present, else home, else `/`.
254: pub fn default_roots() -> Vec<String> {
255:     if let Some(p) = dirs::picture_dir() {
256:         let s = p.to_string_lossy().to_string();
257:         if std::path::Path::new(&s).is_dir() {
258:             return vec![s];
259:         }
260:     }
261:     let home = dirs::home_dir().map(|p| p.to_string_lossy().to_string());
262:     match home {
263:         Some(h) if std::path::Path::new(&h).is_dir() => vec![h],
264:         _ => vec!["/".to_string()],
265:     }
266: }
