268: /// Result of a headless [`run_headless_scan`]/[`smoke_check`] call.
269: #[derive(Clone, Debug)]
270: pub struct ScanSummary {
271:     pub roots: Vec<String>,
272:     pub photos: usize,
273:     pub skipped: usize,
274:     pub partial: bool,
275: }
276: 
277: /// Headless library scan over `roots` (never opens a window).
278: /// Fails with a plain message when there is nothing to scan or a root is
279: /// not a directory — never a silent success.
280: pub fn run_headless_scan(roots: &[String]) -> Result<ScanSummary, String> {
281:     if roots.is_empty() {
282:         return Err("no library roots to scan".into());
283:     }
284:     for r in roots {
285:         if !std::path::Path::new(r).is_dir() {
286:             return Err(format!("not a directory: {r}"));
287:         }
288:     }
289:     let gw = protocol::LocalGateway::default();
290:     let sc = scan::Scanner {
291:         gateway: &gw,
292:         config: scan::ScanConfig { roots: roots.to_vec(), ..Default::default() },
293:         cancelled: false,
294:         published_total: 0,
295:     };
296:     let s = sc.scan();
297:     Ok(ScanSummary {
298:         roots: roots.to_vec(),
299:         photos: s.photos,
300:         skipped: s.skipped,
301:         partial: s.partial,
302:     })
303: }
304: 
305: /// Launch smoke: headless scan + one real thumbnail decode through the
306: /// shared disk cache. Proves the launch path end-to-end (settings load,
307: /// scan, decode, cache store) without needing a display. `Ok` reports
308: /// `thumb_ok` honestly: an empty library is a successful scan with
309: /// `thumb_note` saying there was nothing to decode.
310: #[derive(Clone, Debug)]
311: pub struct SmokeReport {
312:     pub scan: ScanSummary,
313:     pub thumb_ok: bool,
314:     pub thumb_note: String,
315:     pub cache_key_sample: String,
316: }
317: 
318: pub fn smoke_check(roots: &[String]) -> Result<SmokeReport, String> {
319:     let summary = run_headless_scan(roots)?;
320:     let gw = protocol::LocalGateway::default();
321:     let sc = scan::Scanner {
322:         gateway: &gw,
323:         config: scan::ScanConfig { roots: roots.to_vec(), ..Default::default() },
324:         cancelled: false,
325:         published_total: 0,
326:     };
327:     let snap = sc.scan();
328:     if snap.records.is_empty() {
329:         return Ok(SmokeReport {
330:             scan: summary,
331:             thumb_ok: false,
332:             thumb_note: "library empty — scan succeeded, no photo to decode".into(),
333:             cache_key_sample: String::new(),
334:         });
335:     }
336:     let rec = &snap.records[0];
337:     let key = thumb_cache::cache_key(
338:         &rec.path,
339:         256,
340:         rec.mtime_ns,
341:         1,
342:         rec.edit_generation,
343:     );
344:     let job = thumb_cache::ThumbJob {
345:         path: rec.path.clone(),
346:         key: key.clone(),
347:         rung: 256,
348:         edge: 256,
349:         generation: 1,
350:     };
351:     // Same shared disk dir the window uses (~/.cache/smart-files/thumbs).
352:     let dir = thumb_cache::disk_dir();
353:     let _ = std::fs::create_dir_all(&dir);
354:     let decoded = thumb_cache::decode_job(&job, &dir);
355:     let (thumb_ok, thumb_note) = match decoded {
356:         Some(r) => (
357:             r.rgba.len() == (r.w as usize) * (r.h as usize) * 4,
358:             format!(
359:                 "decoded {} ({}×{}, {})",
360:                 rec.name,
361:                 r.w,
362:                 r.h,
363:                 if r.from_disk { "disk cache hit" } else { "fresh decode" }
364:             ),
365:         ),
366:         None => (false, format!("undeodable (declared tile): {}", rec.name)),
367:     };
368:     Ok(SmokeReport { scan: summary, thumb_ok, thumb_note, cache_key_sample: key })
369: }
