371: /// Standalone eframe window (default build, feature `shared-ui` off).
372: /// Wraps one [`PhotoApp`]: the library is scanned once at creation
373: /// (bounded, honest partial state), thumbnails decode through the shared
374: /// [`thumb_cache::ThumbCache`] worker pipeline, and undecodable entries
375: /// show the declared fallback tile — never black. Uses egui's default
376: /// fonts (the shared icon set lives in `smart-ui-egui`, read-only).
377: #[cfg(not(feature = "shared-ui"))]
378: pub struct PhotosWindow {
379:     app: PhotoApp,
380:     roots: Vec<String>,
381:     scan_line: String,
382:     textures: std::collections::HashMap<String, eframe::egui::TextureHandle>,
383:     failed: std::collections::HashSet<String>,
384:     queued: std::collections::HashSet<String>,
385:     selected: Option<String>,
386:     fallback: Option<eframe::egui::TextureHandle>,
387: }
388: 
389: #[cfg(not(feature = "shared-ui"))]
390: impl PhotosWindow {
391:     pub fn new(roots: Vec<String>) -> Self {
392:         let roots = if roots.is_empty() { default_roots() } else { roots };
393:         let gw = protocol::LocalGateway::default();
394:         let (records, scanned, skipped, partial) = {
395:             let sc = scan::Scanner {
396:                 gateway: &gw,
397:                 config: scan::ScanConfig { roots: roots.clone(), ..Default::default() },
398:                 cancelled: false,
399:                 published_total: 0,
400:             };
401:             let snap = sc.scan();
402:             (snap.records, snap.photos, snap.skipped, snap.partial)
403:         };
404:         let mut app = PhotoApp::new(Box::new(gw));
405:         app.library = records;
406:         app.photos.scanned = true;
407:         // Queue thumbnails for the first grid cells (workers decode off
408:         // the UI thread). GRID_CAP cells max — the queue never grows past
409:         // what the grid can display (L10). Rebuilt on later scans would go
410:         // here; for the standalone window this single queue is the set.
411:         const GRID_CAP: usize = 600;
412:         let mut jobs = Vec::new();
413:         for rec in app.library.iter().take(GRID_CAP) {
414:             if rec.kind != model::PhotoKind::Image {
415:                 continue;
416:             }
417:             let key = thumb_cache::cache_key(
418:                 &rec.path,
419:                 256,
420:                 rec.mtime_ns,
421:                 1,
422:                 rec.edit_generation,
423:             );
424:             jobs.push(thumb_cache::ThumbJob {
425:                 path: rec.path.clone(),
426:                 key,
427:                 rung: 256,
428:                 edge: 256,
429:                 generation: 0,
430:             });
431:         }
432:         let mut queued: std::collections::HashSet<String> = jobs.iter().map(|j| j.path.clone()).collect();
433:         app.thumbs.rebuild_visible(jobs);
434:         let scan_line = format!(
435:             "{scanned} photos · {skipped} skipped · roots: {} · partial: {partial}",
436:             roots.join(", ")
437:         );
438:         Self {
439:             app,
440:             roots,
441:             scan_line,
442:             textures: std::collections::HashMap::new(),
443:             failed: std::collections::HashSet::new(),
444:             queued: std::mem::take(&mut queued),
445:             selected: None,
446:             fallback: None,
447:         }
448:     }
449: 
450:     fn filtered(&self) -> Vec<&model::PhotoRecord> {
451:         let q = self.app.photos.search.trim().to_lowercase();
452:         let mut v: Vec<&model::PhotoRecord> = self
453:             .app
454:             .library
455:             .iter()
456:             .filter(|r| q.is_empty() || r.name.to_lowercase().contains(&q))
457:             .collect();
458:         match self.app.photos.sort {
459:             1 => v.sort_by_key(|r| r.mtime_ns),
460:             2 => v.sort_by(|a, b| a.name.cmp(&b.name)),
461:             3 => v.sort_by_key(|r| std::cmp::Reverse(r.size)),
462:             _ => v.sort_by_key(|r| std::cmp::Reverse(r.mtime_ns)),
463:         }
464:         v
465:     }
466: 
467:     fn no_preview_reason(rec: &model::PhotoRecord) -> &'static str {
468:         match rec.kind {
469:             model::PhotoKind::Raw => "RAW indexed, no preview",
470:             model::PhotoKind::Video => "No preview — video still unavailable",
471:             model::PhotoKind::Image => "No preview — undecodable",
472:         }
473:     }
474: }
