476: #[cfg(not(feature = "shared-ui"))]
477: impl eframe::App for PhotosWindow {
478:     fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
479:         let ctx = ui.ctx().clone();
480:         // Drain finished thumbnails into GPU textures.
481:         for r in self.app.thumbs.poll() {
482:             self.queued.remove(&r.path);
483:             let ci = egui::ColorImage::from_rgba_unmultiplied([r.w as usize, r.h as usize], &r.rgba);
484:             let tex = ctx.load_texture(
485:                 format!("smart-photos-thumb-{}", r.path),
486:                 ci,
487:                 egui::TextureOptions::LINEAR,
488:             );
489:             self.textures.insert(r.path.clone(), tex);
490:         }
491:         // When the queue drains, anything still without a texture failed.
492:         if self.app.thumbs.pending() == 0 {
493:             for p in self.queued.clone() {
494:                 if !self.textures.contains_key(&p) {
495:                     self.failed.insert(p);
496:                 }
497:             }
498:             self.queued.clear();
499:         }
500:         if self.fallback.is_none() {
501:             let (tile, _reason) = thumb_cache::ThumbCache::fallback_tile("standby");
502:             let ci = egui::ColorImage::from_rgba_unmultiplied([2usize, 2usize], &tile);
503:             self.fallback = Some(ctx.load_texture(
504:                 "smart-photos-fallback",
505:                 ci,
506:                 egui::TextureOptions::LINEAR,
507:             ));
508:         }
509:         let fallback_id = self.fallback.clone().expect("fallback just created").id();
510: 
511:         ui.heading("Smart Photos (standalone)");
512:         ui.label(self.scan_line.clone());
513:         let shown = self.filtered().len();
514:         ui.label(format!("{shown} in view · click a cell for details"));
515:         let mut search = self.app.photos.search.clone();
516:             ui.horizontal(|ui| {
517:                 ui.label("Search");
518:                 ui.text_edit_singleline(&mut search);
519:                 if ui.button("Clear").clicked() {
520:                     search.clear();
521:                 }
522:                 let sort_label = match self.app.photos.sort {
523:                     1 => "Oldest",
524:                     2 => "Name",
525:                     3 => "Size",
526:                     _ => "Newest",
527:                 };
528:                 if ui.button(format!("Sort: {sort_label}")).clicked() {
529:                     self.app.photos.sort = (self.app.photos.sort + 1) % 4;
530:                 }
531:             });
532:             self.app.photos.search = search;
533: 
534:             // Owned cell snapshot: frees the library borrow so selection
535:             // can mutate self while the grid renders.
536:             const GRID_CAP: usize = 600;
537:             let list = self.filtered();
538:             let shown_total = list.len();
539:             let cells: Vec<(String, String, String, Option<egui::TextureId>, String)> = list
540:                 .iter()
541:                 .take(GRID_CAP)
542:                 .map(|rec| {
543:                     let kind = match rec.kind {
544:                         model::PhotoKind::Image => "image",
545:                         model::PhotoKind::Video => "video",
546:                         model::PhotoKind::Raw => "RAW",
547:                     }
548:                     .to_string();
549:                     let tex = self.textures.get(&rec.path).map(|t| t.id());
550:                     let note = if tex.is_some() {
551:                         String::new()
552:                     } else if self.failed.contains(&rec.path) {
553:                         Self::no_preview_reason(rec).to_string()
554:                     } else if self.queued.contains(&rec.path) {
555:                         "loading …".to_string()
556:                     } else {
557:                         Self::no_preview_reason(rec).to_string()
558:                     };
559:                     (rec.path.clone(), rec.name.clone(), kind, tex, note)
560:                 })
561:                 .collect();
562:             if shown_total > GRID_CAP {
563:                 ui.label(format!(
564:                     "showing first {GRID_CAP} of {shown_total} — search to narrow"
565:                 ));
566:             }
567:             let avail = ui.available_width();
568:             let cols = (avail / 148.0).floor().max(1.0) as usize;
569:             let mut clicked: Option<String> = None;
570:             egui::ScrollArea::vertical()
571:                 .auto_shrink([false, false])
572:                 .show(ui, |ui| {
573:                     egui::Grid::new("photos-grid")
574:                         .spacing([8.0, 8.0])
575:                         .show(ui, |ui| {
576:                             for (j, (path, name, kind, tex, note)) in cells.iter().enumerate() {
577:                                 let is_sel = self.selected.as_ref() == Some(path);
578:                                 let resp = ui.vertical(|ui| {
579:                                     let img = match tex {
580:                                         Some(id) => {
581:                                             let img = egui::Image::new((*id, egui::vec2(128.0, 96.0)))
582:                                                 .fit_to_exact_size(egui::vec2(128.0, 96.0));
583:                                             ui.add(img)
584:                                         }
585:                                         None => {
586:                                             let img = egui::Image::new((
587:                                                 fallback_id,
588:                                                 egui::vec2(128.0, 96.0),
589:                                             ))
590:                                             .fit_to_exact_size(egui::vec2(128.0, 96.0));
591:                                             let resp = ui.add(img);
592:                                             if !note.is_empty() {
593:                                                 ui.label(note.clone());
594:                                             }
595:                                             resp
596:                                         }
597:                                     };
598:                                     let cap = format!("{name} · {kind}");
599:                                     let cap = if is_sel { format!("● {cap}") } else { cap };
600:                                     ui.label(cap);
601:                                     img
602:                                 });
603:                                 if resp.response.clicked() {
604:                                     clicked = Some(path.clone());
605:                                 }
606:                                 if (j + 1) % cols == 0 {
607:                                     ui.end_row();
608:                                 }
609:                             }
610:                         });
611:                 });
612:             if let Some(p) = clicked {
613:                 self.selected = Some(p);
614:             }
615:             if let Some(sel) = self.selected.clone() {
616:                 let rec = self.app.library.iter().find(|r| r.path == sel).cloned();
617:                 match rec {
618:                     Some(rec) => {
619:                         ui.separator();
620:                         ui.label(format!(
621:                             "{} · {} · {:?} · taken: {} ({}) · {:.1} KiB",
622:                             rec.name,
623:                             rec.path,
624:                             rec.kind,
625:                             rec.taken_at
626:                                 .map(|t| t.to_string())
627:                                 .unwrap_or_else(|| "unknown".into()),
628:                             rec.taken_source.sentence(),
629:                             rec.size as f64 / 1024.0,
630:                         ));
631:                         ui.label(
632:                             "Standalone preview — the full viewer/editor is the shared frontend (feature shared-ui).",
633:                         );
634:                     }
635:                     None => {
636:                         self.selected = None;
637:                     }
638:                 }
639:             }
640:             ui.separator();
641:             ui.label(format!(
642:                 "roots: {} · close the window to quit · headless: smart-photos --scan / --smoke",
643:                 self.roots.join(", ")
644:             ));
645:     }
646: }
