//!
//! Hypnotic breathing: brightness follows `0.65 + 0.35·sin(2πt/1.4)` so the
//! caret never hard-blinks. Jump (sticky cursor after a click / key) uses
//! the shared spring `spring_to(ctx, "caret-jump", v, 420.0, 26.0)`.
//!
//! Pure math lives here so it can be unit-tested without a live `Context`.
use std::f32::consts::PI;

/// Caret breathing period, seconds.
pub const CARET_PERIOD: f32 = 1.4;
/// Caret jump spring stiffness / damping (all apps, one set of constants).
pub const CARET_JUMP_STIFFNESS: f32 = 420.0;
pub const CARET_JUMP_DAMPING: f32 = 26.0;

/// Caret brightness at time `t` (seconds): `0.65 + 0.35·sin(2πt/1.4)` ∈ [0.30, 1.00].
/// Deterministic — the same `t` always yields the same brightness (no flicker on reflow).
pub fn caret_brightness(t: f32) -> f32 {
    0.65 + 0.35 * (2.0 * PI * t / CARET_PERIOD).sin()
}

/// Caret alpha for drawing, derived from [`caret_brightness`]. Clamped to [0, 1].
pub fn caret_alpha(t: f32) -> f32 {
    caret_brightness(t).clamp(0.0, 1.0)
}

/// Caret x-position after a jump: spring `pos → target` with 420/26.
/// Delegates to the shared `paint::spring_to` so every app moves identically.
pub fn caret_jump(ctx: &egui::Context, id: impl std::hash::Hash + std::fmt::Debug + Clone, target: f32) -> f32 {
    crate::paint::spring_to(ctx, ("caret-jump", id), target, CARET_JUMP_STIFFNESS, CARET_JUMP_DAMPING)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn breathing_stays_in_range() {
        for i in 0..1000 {
            let t = i as f32 / 100.0;
            let b = caret_brightness(t);
            assert!((0.30..=1.00).contains(&b), "t={t} b={b}");
            let a = caret_alpha(t);
            assert!((0.0..=1.0).contains(&a));
        }
    }

    #[test]
    fn breathing_is_periodic() {
        let a = caret_brightness(0.0);
        let b = caret_brightness(CARET_PERIOD);
        assert!((a - b).abs() < 1e-5, "period drift {a} vs {b}");
        // Mid-period is the trough: sin(π) = 0 → 0.65.
        assert!((caret_brightness(CARET_PERIOD * 0.5) - 0.65).abs() < 1e-5);
    }

    #[test]
    fn spring_constants_are_canonical() {
        assert_eq!((CARET_JUMP_STIFFNESS, CARET_JUMP_DAMPING), (420.0, 26.0));
    }
}

//! Motion law — the ONE animation contract for every app.
//!
//! Springs (all apps, one set of constants):
//! - enter/exit: stiffness 220, damping 24 (pop with a touch of overshoot)
//! - hover: stiffness 300, damping 28 (fast, no bounce)
//! - pack/commit (row → card commit): stiffness 420, damping 26 (matches caret jump)
//!
//! Segmented controls: 32 px icon buttons, 36 px text buttons (single size
//! per row — never mixed 32/36 on the same row).
//!
//! Menu jitter law: a menu's open position is measured ONCE (first frame,
//! `age == 0`) and then frozen. Later frames only animate opacity/scale.
//! Re-measuring every frame (e.g. re-wrapping text as fonts load) is the
//! jitter bug — the menu visibly jumping while open. `MenuAnchor` encodes it.

/// Enter/exit spring.
pub const SPRING_ENTER_STIFFNESS: f32 = 220.0;
pub const SPRING_ENTER_DAMPING: f32 = 24.0;
/// Hover spring.
pub const SPRING_HOVER_STIFFNESS: f32 = 300.0;
pub const SPRING_HOVER_DAMPING: f32 = 28.0;
/// Pack/commit spring (matches caret jump).
pub const SPRING_PACK_STIFFNESS: f32 = 420.0;
pub const SPRING_PACK_DAMPING: f32 = 26.0;

/// Segmented control sizes.
pub const SEGMENT_ICON: f32 = 32.0;
pub const SEGMENT_TEXT: f32 = 36.0;

/// Current value of the enter/exit spring towards `target` for `id`.
pub fn enter(ctx: &egui::Context, id: impl std::hash::Hash + std::fmt::Debug + Clone, target: f32) -> f32 {
    crate::paint::spring_to(ctx, ("anim-enter", id), target, SPRING_ENTER_STIFFNESS, SPRING_ENTER_DAMPING)
}

/// Current value of the hover spring.
pub fn hover(ctx: &egui::Context, id: impl std::hash::Hash + std::fmt::Debug + Clone, target: f32) -> f32 {
    crate::paint::spring_to(ctx, ("anim-hover", id), target, SPRING_HOVER_STIFFNESS, SPRING_HOVER_DAMPING)
}

/// Menu open anchor: measured once on open, frozen afterwards.
/// `first_frame_pos` is the clamped position computed on `age == 0`;
/// `stored_pos` is what we keep while the menu stays open.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MenuAnchor {
    pub pos: egui::Pos2,
    pub measured: bool,
}

impl MenuAnchor {
    /// Open: measure `pos` once.
    pub fn open(pos: egui::Pos2) -> Self {
        Self { pos, measured: true }
    }
    /// Next frame: reuse the stored position (no re-measure → no jitter).
    pub fn frame(&self, candidate: egui::Pos2) -> egui::Pos2 {
        if self.measured {
            self.pos
        } else {
            candidate
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spring_constants_are_canonical() {
        assert_eq!((SPRING_ENTER_STIFFNESS, SPRING_ENTER_DAMPING), (220.0, 24.0));
        assert_eq!((SPRING_HOVER_STIFFNESS, SPRING_HOVER_DAMPING), (300.0, 28.0));
        assert_eq!((SPRING_PACK_STIFFNESS, SPRING_PACK_DAMPING), (420.0, 26.0));
    }

    #[test]
    fn segment_sizes() {
        assert_eq!((SEGMENT_ICON, SEGMENT_TEXT), (32.0, 36.0));
    }

    #[test]
    fn menu_anchor_never_jitters() {
        let a = MenuAnchor::open(egui::pos2(100.0, 50.0));
        // Even if a later frame computes a different candidate, the anchor holds.
        assert_eq!(a.frame(egui::pos2(999.0, 999.0)), egui::pos2(100.0, 50.0));
    }
}

