//! File chooser component (canonical — every app shares ONE picker).
//!
//! Features: New Folder, live search, multi-select with sort (Name/Size/Date),
//! and the XDG portal contract: when the OS portal is available the native
//! portal is used and this component is not shown; otherwise this in-app
//! picker is the honest fallback (no fake native dialog).
//!
//! Pure state lives here so it can be unit-tested without a live `Context`.

/// XDG portal contract — what a portal FileChooser request looks like.
/// Documented for every host; the native path is only taken when the
/// portal is actually available (see [`portal_available`]).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PortalRequest {
    /// Parent window handle id (empty on hosts without window ids).
    pub parent_window: String,
    /// File dialog title, e.g. "Choose a photo".
    pub title: String,
    /// Initial directory as a `/`-separated path.
    pub start_dir: String,
    /// File filters as glob patterns (`["*.png", "*.jpg"]`). Empty = all files.
    pub filters: Vec<String>,
    /// Multi-select allowed.
    pub multi: bool,
    /// Save-dialog mode (the user is choosing a destination name).
    pub save: bool,
}

/// Is an XDG portal usable right now? Honest: checks for `xdg-desktop-portal`
/// on PATH (or always true on wasm, where the browser picker is the portal).
#[cfg(not(target_arch = "wasm32"))]
pub fn portal_available() -> bool {
    std::process::Command::new("which")
        .arg("xdg-desktop-portal")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

#[cfg(target_arch = "wasm32")]
pub fn portal_available() -> bool {
    true
}

/// How the picker sorts its entries (multi-sort: primary + secondary key).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum PickerSort {
    #[default]
    Name,
    Size,
    Date,
    Kind,
}

impl PickerSort {
    pub fn label(self) -> &'static str {
        match self {
            PickerSort::Name => "Name",
            PickerSort::Size => "Size",
            PickerSort::Date => "Date",
            PickerSort::Kind => "Kind",
        }
    }
}

/// In-app picker state (the portal fallback).
#[derive(Clone, Debug, Default)]
pub struct PickerState {
    /// Live search text (filters the current folder).
    pub query: String,
    /// Sort order.
    pub sort: PickerSort,
    /// Multi-select selection (paths as `/`-separated strings).
    pub selection: Vec<String>,
    /// "New Folder" inline name being edited (empty = not creating).
    pub new_folder_name: String,
    /// Save-mode file name (for save dialogs).
    pub save_name: String,
    /// Whether the dialog is open.
    pub open: bool,
}

impl PickerState {
    pub fn open_for(title: &str, start_dir: &str) -> Self {
        let _ = title;
        let _ = start_dir;
        Self { open: true, ..Default::default() }
    }

    /// Filter entries by the live search query (substring, case-insensitive).
    pub fn filter<'a>(&self, entries: impl IntoIterator<Item = &'a str>) -> Vec<&'a str> {
        let q = self.query.trim().to_lowercase();
        let mut v: Vec<&str> = entries.into_iter().collect();
        if !q.is_empty() {
            v.retain(|n| n.to_lowercase().contains(&q));
        }
        v
    }

    /// Portal request this picker would mirror natively.
    pub fn portal_request(&self, title: &str, start_dir: &str, multi: bool) -> PortalRequest {
        PortalRequest {
            parent_window: String::new(),
            title: title.to_string(),
            start_dir: start_dir.to_string(),
            filters: vec![],
            multi,
            save: !self.save_name.is_empty(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn search_filters_case_insensitive() {
        let mut p = PickerState::default();
        p.query = "pho".into();
        assert_eq!(p.filter(["photo.jpg", "notes.txt", "Phoneme.wav"]), vec!["photo.jpg", "Phoneme.wav"]);
        p.query.clear();
        assert_eq!(p.filter(["a", "b"]), vec!["a", "b"]);
    }

    #[test]
    fn portal_request_mirrors_state() {
        let mut p = PickerState::default();
        p.save_name = "out.png".into();
        let r = p.portal_request("Save", "/home/u", false);
        assert!(r.save);
        assert_eq!(r.start_dir, "/home/u");
    }

    #[test]
    fn sort_labels() {
        assert_eq!(PickerSort::Name.label(), "Name");
        assert_eq!(PickerSort::Date.label(), "Date");
    }
}

//! Global drag & drop component (canonical — every app shares ONE DnD).
//!
//! MIME contract (`x-special/gnome-copied-files`): the OS clipboard/drag
//! standard used by GNOME interop. [`X_SPECIAL_MIME`] is the mime id every
//! host reads/writes; [`DragPayload`] is the in-process token.
//!
//! The drop effect is decided once at drop time in `lib.rs` via
//! [`resolve_effect`] — no per-surface re-derivation (no jitter between
//! ghost and commit).

/// `x-special/gnome-copied-files` — the GNOME clipboard drag mime.
/// Payload text: `copy\n<uri>\n` (or `cut\n<uri>\n`), URIs are `file://`.
pub const X_SPECIAL_MIME: &str = "x-special/gnome-copied-files";
/// Plain-text fallback mime (when `x-special` is unavailable).
pub const TEXT_URI_LIST_MIME: &str = "text/uri-list";

/// In-process drag token carried by the framework drag ghost.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DragPayload {
    /// Source items as `/`-separated paths.
    pub items: Vec<String>,
    /// Total bytes (for the ghost "Move N·size→X" line).
    pub bytes: u64,
    /// True when the drag started as cut (move semantics).
    pub cut: bool,
    /// Modifier keys at drag start (Alt/Ctrl = force copy).
    pub force_copy: bool,
}

impl DragPayload {
    pub fn count(&self) -> usize {
        self.items.len()
    }
}

/// What the drop does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DropEffect {
    /// Move items (same device, no modifier).
    Move,
    /// Copy items (Alt/Ctrl, or cross-device).
    Copy,
    /// Tag items (drop on a tag).
    Tag,
    /// Move to trash.
    Trash,
    /// Pin to Favorites.
    Pin,
    /// No-op (destination == source).
    Noop,
}

/// Resolve the drop effect from the payload + modifiers + destination kind.
/// Pure so every host resolves identically.
pub fn resolve_effect(payload: &DragPayload, modifier_copy: bool, cross_device: bool, same_folder: bool, on_tag: bool, on_trash: bool, on_pin: bool) -> DropEffect {
    if on_tag {
        return DropEffect::Tag;
    }
    if on_trash {
        return DropEffect::Trash;
    }
    if on_pin {
        return DropEffect::Pin;
    }
    if same_folder && !payload.cut && !modifier_copy && !cross_device && !payload.force_copy {
        return DropEffect::Noop;
    }
    if modifier_copy || cross_device || payload.force_copy || !payload.cut {
        DropEffect::Copy
    } else {
        DropEffect::Move
    }
}

/// Encode a payload as `x-special/gnome-copied-files` text.
pub fn encode_x_special(payload: &DragPayload) -> String {
    let verb = if payload.cut { "cut" } else { "copy" };
    let mut s = format!("{verb}\n");
    for item in &payload.items {
        s.push_str(&format!("file://{item}\n"));
    }
    s
}

/// Decode `x-special` text back into items (`cut`/`copy` + `file://` URIs).
pub fn decode_x_special(text: &str) -> Option<Vec<String>> {
    let mut lines = text.lines();
    let verb = lines.next().unwrap_or("").trim();
    if verb != "copy" && verb != "cut" {
        return None;
    }
    let v: Vec<String> = lines
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .map(|l| l.trim_start_matches("file://").to_string())
        .collect();
    if v.is_empty() {
        None
    } else {
        Some(v)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn payload(cut: bool) -> DragPayload {
        DragPayload { items: vec!["/a".into(), "/b".into()], bytes: 2048, cut, force_copy: false }
    }

    #[test]
    fn effect_resolution() {
        assert_eq!(resolve_effect(&payload(true), false, false, false, false, false, false), DropEffect::Move);
        assert_eq!(resolve_effect(&payload(true), true, false, false, false, false, false), DropEffect::Copy);
        assert_eq!(resolve_effect(&payload(true), false, true, false, false, false, false), DropEffect::Copy);
        assert_eq!(resolve_effect(&payload(false), false, false, false, false, false, false), DropEffect::Copy);
        assert_eq!(resolve_effect(&payload(true), false, false, true, false, false, false), DropEffect::Noop);
        assert_eq!(resolve_effect(&payload(true), true, false, true, false, false, false), DropEffect::Copy);
        assert_eq!(resolve_effect(&payload(true), false, false, false, true, false, false), DropEffect::Tag);
        assert_eq!(resolve_effect(&payload(true), false, false, false, false, true, false), DropEffect::Trash);
    }

    #[test]
    fn x_special_roundtrip() {
        let p = payload(true);
        let t = encode_x_special(&p);
        assert!(t.starts_with("cut\n"));
        assert_eq!(decode_x_special(&t), Some(vec!["/a".to_string(), "/b".to_string()]));
        assert_eq!(decode_x_special("nonsense"), None);
        assert_eq!(X_SPECIAL_MIME, "x-special/gnome-copied-files");
    }
}

//! Dialog law (canonical — every sheet/modal follows the same contract).
//!
//! 1. **Wrap-close**: clicking the scrim closes; `Esc` closes; close button
//!    is top-right at `card.top() + 20` (the `+20` rule — never ad-hoc).
//! 2. **Grid**: 8 px spacing, content inset 24 px, close orb 30 px.
//! 3. **Springs**: open/close use the enter/exit spring (220/24); reduced
//!    motion turns springs into fades.
//! 4. **No hardcoded heights**: the card height comes from content
//!    (`card_h = min(content_h, win_h - 48)`), never a fixed number that
//!    leaves gaps when fonts scale.

/// Close-button vertical offset from the card top.
pub const CLOSE_TOP_OFFSET: f32 = 20.0;
/// Close orb size.
pub const CLOSE_SIZE: f32 = 30.0;
/// Content inset.
pub const CONTENT_INSET: f32 = 24.0;
/// Grid spacing.
pub const GRID: f32 = 8.0;
/// Minimum distance from the window edge (card max size `win - 48`).
pub const EDGE_MARGIN: f32 = 48.0;

/// Clamp a desired card height to the window so no gap/overflow appears when
/// text scales: `h = min(desired, win_h - EDGE_MARGIN)`.
pub fn clamp_card(desired_h: f32, win_h: f32) -> f32 {
    desired_h.min((win_h - EDGE_MARGIN).max(160.0))
}

/// Open/close spring value for a dialog `age` (seconds).
pub fn dialog_open(age: f32, reduce_motion: bool) -> f32 {
    if reduce_motion {
        (age * 8.0).clamp(0.0, 1.0)
    } else {
        crate::paint::spring_out(age)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn close_law() {
        assert_eq!(CLOSE_TOP_OFFSET, 20.0);
        assert_eq!(CLOSE_SIZE, 30.0);
    }

    #[test]
    fn card_never_overflows() {
        assert_eq!(clamp_card(800.0, 760.0), 712.0);
        assert_eq!(clamp_card(300.0, 760.0), 300.0);
    }

    #[test]
    fn reduced_motion_is_a_fade() {
        assert_eq!(dialog_open(99.0, true), 1.0);
        assert_eq!(dialog_open(0.0, true), 0.0);
    }
}

//! Assistant (AI) panel component (canonical — the one AI composer every app shares).
//!
//! Geometry is contractual: header 62, composer 108, body scrollable; the
//! input well is 16 px radius, single-line, with `Enter` to send and `Esc`
//! to blur. The chip reads "Smart Neura · local" and the send button is a
//! 32 px icon button (`arrow-right-up`).
//!
//! Pure geometry lives here so hosts cannot drift.

/// Panel header height.
pub const HEADER_H: f32 = 62.0;
/// Composer height.
pub const COMPOSER_H: f32 = 108.0;
/// Input well radius.
pub const WELL_R: f32 = 16.0;
/// Send button size (32 px icon button per the segmented law).
pub const SEND_SIZE: f32 = 32.0;
/// Composer bottom inset.
pub const COMPOSER_INSET: f32 = 42.0;

/// Composer rect given the panel.
pub fn composer_rect(panel: egui::Rect) -> egui::Rect {
    let top = panel.max.y - COMPOSER_INSET - COMPOSER_H + 66.0;
    egui::Rect::from_min_size(egui::pos2(panel.min.x + 18.0, top), egui::vec2(panel.width() - 36.0, COMPOSER_H - 66.0))
}

