    }
}

//! Capture component (canonical — screen capture for every app).
//!
//! This is the UI-side contract: the component requests a frame, the host
//! (desktop screenshot tool / browser API) supplies PNG bytes. No host
//! screenshot code lives in this crate — backends are disposable.
//!
//! Honest states: `Captured` (real bytes), `Unavailable` (host declined),
//! `Cancelled` (user backed out). Never a fake success.

/// Result of one capture attempt.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CaptureOutcome {
    /// Real PNG bytes captured (first bytes are the PNG magic).
    Captured(Vec<u8>),
    /// Host could not provide a frame (permissions, headless, ...).
    Unavailable(String),
    /// User cancelled.
    Cancelled,
}

impl CaptureOutcome {
    pub fn is_png(&self) -> bool {
        matches!(self, CaptureOutcome::Captured(b) if b.len() >= 8 && b.starts_with(b"\x89PNG\r\n\x1a\n"))
    }
}

/// Capture button state (for aria / tooltip labelling).
#[derive(Clone, Debug, Default)]
pub struct CaptureState {
    pub busy: bool,
    pub last_note: String,
}

impl CaptureState {
    pub fn note(&mut self, outcome: &CaptureOutcome) -> String {
        self.busy = false;
        self.last_note = match outcome {
            CaptureOutcome::Captured(b) => format!("Captured {} bytes", b.len()),
            CaptureOutcome::Unavailable(e) => format!("Capture unavailable: {e}"),
            CaptureOutcome::Cancelled => "Capture cancelled".into(),
        };
        self.last_note.clone()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn png_detection() {
        assert!(CaptureOutcome::Captured(b"\x89PNG\r\n\x1a\n....".to_vec()).is_png());
        assert!(!CaptureOutcome::Captured(b"not a png".to_vec()).is_png());
        assert!(!CaptureOutcome::Cancelled.is_png());
    }
}

