//! Treemap layout (the `squarify` idea from the recreate branch, ported).
//!
//! Pure layout only — no VFS types — so the storage Map view can place
//! `ScanNode`s without knowing where the bytes came from.
//!
//! `layout` packs `(id, bytes)` rects into `bounds`, sorted by bytes desc,
//! returning one `(id, rect)` per input with the id preserved for click
//! mapping. Zero-byte inputs are skipped (they have no area).

/// Axis-aligned rect in `bounds` space.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TreemapRect {
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
}

impl TreemapRect {
    pub fn area(&self) -> f32 {
        self.w * self.h
    }
}

impl From<egui_rect> for TreemapRect {
    fn from(r: egui_rect) -> Self {
        Self { x: r.x, y: r.y, w: r.w, h: r.h }
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct egui_rect {
    pub x: f32,
    pub y: f32,
    pub w: f32,
    pub h: f32,
}

/// Pack `items` (id, bytes) into `bounds`. Output preserves input order of
/// ids; layout itself is sorted desc for squareness.
pub fn layout(items: &[(String, u64)], bounds: TreemapRect) -> Vec<(String, TreemapRect)> {
    let total: u64 = items.iter().map(|(_, b)| *b).sum();
    if total == 0 || bounds.w <= 0.0 || bounds.h <= 0.0 {
        return vec![];
    }
    let mut sorted: Vec<&(String, u64)> = items.iter().filter(|(_, b)| *b > 0).collect();
    sorted.sort_by(|a, b| b.1.cmp(&a.1));
    let total_area = bounds.w * bounds.h;
    let mut out: Vec<(String, TreemapRect)> = Vec::with_capacity(sorted.len());

    // Row-based squarify: fill rows along the shorter side, then stack rows.
    // Classic squarified treemap, simplified: one row per batch, batch
    // chosen to minimise the worst aspect ratio.
    struct Row {
        ids: Vec<(String, u64)>,
        total: u64,
    }
    let mut rows: Vec<Row> = vec![];
    let mut cur: Vec<(String, u64)> = vec![];
    let mut cur_total = 0u64;
    for (id, bytes) in sorted {
        let trial = cur_total + *bytes;
        let worst = |row_total: u64, max_b: u64, short: f32, scale: f32| -> f32 {
            let row_h = (row_total as f32 * scale) / short.max(1.0);
            let rect_w_scale = short / row_h.max(1.0);
            let max_rect = (max_b as f32 * scale) * rect_w_scale;
            (row_h.max(max_rect) / row_h.min(max_rect)).max(1.0)
        };
        let scale = total_area / total as f32;
        let short = bounds.w.min(bounds.h);
        let max_b = cur.iter().map(|(_, b)| *b).max().unwrap_or(*bytes).max(*bytes);
        if cur.is_empty() {
            cur.push((id.clone(), *bytes));
            cur_total = trial;
        } else {
            let before = worst(cur_total, max_b, short, scale);
            let after = worst(trial, max_b, short, scale);
            if after <= before {
                cur.push((id.clone(), *bytes));
                cur_total = trial;
            } else {
                rows.push(Row { ids: std::mem::take(&mut cur), total: cur_total });
                cur.push((id.clone(), *bytes));
                cur_total = *bytes;
            }
        }
    }
    if !cur.is_empty() {
        rows.push(Row { ids: cur, total: cur_total });
    }

    // Place rows: rows stack down the long axis.
    let vertical_stack = bounds.h >= bounds.w;
    let (mut cx, mut cy) = (bounds.x, bounds.y);
    let (mut cw, mut ch) = (bounds.w, bounds.h);
    for row in &rows {
        let row_frac = row.total as f32 / total as f32;
        if vertical_stack {
            let row_h = ch * row_frac;
            let mut x = cx;
            for (id, bytes) in &row.ids {
                let w = cw * (*bytes as f32 / row.total as f32);
                out.push((id.clone(), TreemapRect { x, y: cy, w, h: row_h }));
                x += w;
            }
            cy += row_h;
            ch -= row_h;
        } else {
            let row_w = cw * row_frac;
            let mut y = cy;
            for (id, bytes) in &row.ids {
                let h = ch * (*bytes as f32 / row.total as f32);
                out.push((id.clone(), TreemapRect { x: cx, y, w: row_w, h }));
                y += h;
            }
            cx += row_w;
            cw -= row_w;
        }
    }
    // Restore input order for stable hit-mapping.
    out.sort_by_key(|(id, _)| {
        items.iter().position(|(i, _)| i == id).unwrap_or(usize::MAX)
    });
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn items(v: &[(&str, u64)]) -> Vec<(String, u64)> {
        v.iter().map(|(a, b)| (a.to_string(), *b)).collect()
    }

    #[test]
    fn fills_bounds() {
        let b = TreemapRect { x: 0.0, y: 0.0, w: 100.0, h: 100.0 };
        let laid = layout(&items(&[("a", 50), ("b", 30), ("c", 20)]), b);
        assert_eq!(laid.len(), 3);
        let total: f32 = laid.iter().map(|(_, r)| r.area()).sum();
        assert!((total - 10_000.0).abs() < 1.0, "total {total}");
        for (_, r) in &laid {
            assert!(r.w > 0.0 && r.h > 0.0);
            assert!(r.x >= -0.01 && r.y >= -0.01 && r.x + r.w <= 100.01 && r.y + r.h <= 100.01);
        }
    }

    #[test]
    fn bigger_gets_bigger() {
        let b = TreemapRect { x: 0.0, y: 0.0, w: 200.0, h: 100.0 };
        let laid = layout(&items(&[("small", 10), ("big", 90)]), b);
        let small = laid.iter().find(|(id, _)| id == "small").unwrap().1.area();
        let big = laid.iter().find(|(id, _)| id == "big").unwrap().1.area();
        assert!(big > small * 5.0, "big {big} small {small}");
    }

    #[test]
    fn empty_and_zero_inputs() {
        let b = TreemapRect { x: 0.0, y: 0.0, w: 10.0, h: 10.0 };
        assert!(layout(&[], b).is_empty());
        assert!(layout(&items(&[("z", 0)]), b).is_empty());
        assert!(layout(&items(&[("a", 1)]), TreemapRect { x: 0.0, y: 0.0, w: 0.0, h: 10.0 }).is_empty());
    }
}

//! Storage analysis (the eiga `analyze.rs` idea, ported as a classifier).
//!
//! `classify` labels every large file one of: **Safe** (safe to trash —
//! caches, temp, logs), **Review** (large, user should look), or **Keep**.
//! The storage view paints "Biggest wins" from this so the user sees one
//! honest Safe/Review chip per row instead of a raw byte count.
//!
//! Pure functions — no VFS access — so they run on any `Scan` output.

/// Classification verdict for a large file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verdict {
    /// Safe to trash (cache, temp, junk).
    Safe,
    /// Large — the user should review before trashing.
    Review,
    /// Not a cleanup candidate.
    Keep,
}

impl Verdict {
    pub fn label(self) -> &'static str {
        match self {
            Verdict::Safe => "Safe",
            Verdict::Review => "Review",
            Verdict::Keep => "Keep",
        }
    }
}

/// Extensions / name fragments that are always safe to trash.
const JUNK_EXTS: &[&str] = &["tmp", "temp", "log", "cache", "bak", "old", "orig", "swp"];
const JUNK_DIRS: &[&str] = &["cache", "caches", "tmp", "temp", "logs", "node_modules/.cache", ".git/objects"];

fn ext_of(name: &str) -> String {
    name.rsplit('.').next().unwrap_or("").to_lowercase()
}

/// Classify `path` (lowercased match) with `size` bytes.
pub fn classify(path: &str, size: u64) -> Verdict {
    let lower = path.to_lowercase();
    if JUNK_DIRS.iter().any(|d| lower.contains(d)) {
        return Verdict::Safe;
    }
    let ext = ext_of(&lower);
    if JUNK_EXTS.contains(&ext.as_str()) {
        return Verdict::Safe;
    }
    if size >= 100 << 20 {
        return Verdict::Review;
    }
    Verdict::Keep
}

/// One "Biggest wins" row: a large file + its verdict.
#[derive(Clone, Debug)]
pub struct BiggestWin {
    pub path: String,
    pub bytes: u64,
    pub verdict: Verdict,
}

/// Build the "Biggest wins" list from `(path, bytes)`: keep the biggest 10
/// that are Safe or Review, biggest first.
pub fn biggest_wins(files: &[(String, u64)]) -> Vec<BiggestWin> {
    let mut v: Vec<BiggestWin> = files
        .iter()
        .map(|(p, b)| BiggestWin { path: p.clone(), bytes: *b, verdict: classify(p, *b) })
        .filter(|w| w.verdict != Verdict::Keep)
        .collect();
    v.sort_by(|a, b| b.bytes.cmp(&a.bytes));
    v.truncate(10);
    v
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn verdicts() {
        assert_eq!(classify("/home/u/.cache/foo.bin", 1), Verdict::Safe);
        assert_eq!(classify("/tmp/x.tmp", 5), Verdict::Safe);
        assert_eq!(classify("/home/u/video.mp4", 200 << 20), Verdict::Review);
        assert_eq!(classify("/home/u/doc.txt", 12), Verdict::Keep);
        assert_eq!(Verdict::Safe.label(), "Safe");
    }

    #[test]
    fn biggest_wins_sorts_and_caps() {
        let files = vec![
            ("a.tmp".to_string(), 500u64),
            ("b.mp4".to_string(), 200 << 20),
            ("small.txt".to_string(), 10u64),
            ("c.log".to_string(), 300u64),
        ];
        let wins = biggest_wins(&files);
        assert_eq!(wins.len(), 3);
        assert_eq!(wins[0].path, "b.mp4");
        assert_eq!(wins[0].verdict, Verdict::Review);
        assert!(wins.iter().all(|w| w.verdict != Verdict::Keep));
    }
}

//! Undo stack (the develop undo, ported as a pure stack).
//!
//! Every reversible operation pushes its inverse-capable description here;
//! `pop` returns the op the caller executes backwards (restore from trash,
//! rename back, delete the created item, move items home). Depth is bounded
//! so the stack itself never leaks.
//!
//! The stack is pure (locations only) — the backend/job layer executes the
//! inverse, so this crate stays UI-free.

use crate::model::Location;

/// Default undo depth (Settings can override: "Undo depth" row).
pub const DEFAULT_DEPTH: usize = 50;

/// One reversible operation.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum UndoOp {
    /// Items were moved to trash; undo restores them.
    Trash(Vec<Location>),
    /// `from` was renamed to `to`; undo renames back.
    Rename { from: Location, to: Location },
    /// `loc` was created; undo deletes it.
    Create(Location),
    /// `srcs` were moved to `dest`; undo moves them back.
    Move { srcs: Vec<Location>, dest: Location },
}

impl UndoOp {
    pub fn label(&self) -> String {
        match self {
            UndoOp::Trash(v) => format!("Move {} to Trash", v.len()),
            UndoOp::Rename { from, to } => format!("Rename {} → {}", from.name(), to.name()),
            UndoOp::Create(l) => format!("Create {}", l.name()),
            UndoOp::Move { srcs, dest } => format!("Move {} to {}", srcs.len(), dest.name()),
        }
    }

    pub fn locations(&self) -> Vec<Location> {
        match self {
            UndoOp::Trash(v) => v.clone(),
            UndoOp::Rename { from, to } => vec![from.clone(), to.clone()],
            UndoOp::Create(l) => vec![l.clone()],
            UndoOp::Move { srcs, dest } => {
                let mut v = srcs.clone();
                v.push(dest.clone());
                v
            }
        }
    }
}

/// Bounded undo stack.
#[derive(Clone, Debug)]
pub struct UndoStack {
    ops: Vec<UndoOp>,
    depth: usize,
}

impl Default for UndoStack {
    fn default() -> Self {
        Self::new(DEFAULT_DEPTH)
    }
}

impl UndoStack {
    pub fn new(depth: usize) -> Self {
        Self { ops: Vec::new(), depth: depth.max(1) }
    }

    pub fn push(&mut self, op: UndoOp) {
        self.ops.push(op);
        while self.ops.len() > self.depth {
            self.ops.remove(0);
        }
    }

    /// Pop the most recent op (the caller executes its inverse).
    pub fn pop(&mut self) -> Option<UndoOp> {
        self.ops.pop()
    }

    pub fn peek(&self) -> Option<&UndoOp> {
        self.ops.last()
    }

    pub fn len(&self) -> usize {
        self.ops.len()
    }

    pub fn is_empty(&self) -> bool {
        self.ops.is_empty()
    }

    pub fn clear(&mut self) {
        self.ops.clear();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn loc(p: &str) -> Location {
        Location::new("local", p)
    }

    #[test]
    fn push_pop_lifo() {
        let mut s = UndoStack::new(3);
        s.push(UndoOp::Create(loc("/a")));
        s.push(UndoOp::Rename { from: loc("/x"), to: loc("/y") });
        assert_eq!(s.len(), 2);
        let op = s.pop().unwrap();
        assert_eq!(op.label(), "Rename x → y");
        assert_eq!(s.len(), 1);
    }

    #[test]
    fn depth_is_bounded() {
        let mut s = UndoStack::new(2);
        for i in 0..5 {
            s.push(UndoOp::Create(loc(&format!("/f{i}"))));
        }
        assert_eq!(s.len(), 2);
        assert!(s.peek().unwrap().label().contains("f4"));
    }

    #[test]
    fn empty_stack() {
        let mut s = UndoStack::default();
        assert!(s.pop().is_none());
        assert!(s.is_empty());
    }
}

//! AI plan layer (the recreate `PlanOp` pattern, ported).
//!
//! Every AI action is a **plan**: a dry-run list of moves the user can see,
//! approve, or cancel. Nothing executes until the user confirms — that is
//! what makes AI actions reversible by default.
//!
//! Pure: planning only looks at names/kinds, never touches the VFS.

use crate::model::{Entry, Kind};

/// One planned move: `src` → `dst` (paths as `/`-separated strings).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PlanMove {
    pub src: String,
    pub dst: String,
}

/// A reversible AI plan.
#[derive(Clone, Debug, Default)]
pub struct Plan {
    pub title: String,
    pub moves: Vec<PlanMove>,
    /// True once the user approved (executing is the caller's job).
    pub approved: bool,
}

impl Plan {
    pub fn is_empty(&self) -> bool {
        self.moves.is_empty()
    }

    pub fn len(&self) -> usize {
        self.moves.len()
    }
}

/// Plan an "organise by kind" pass: every top-level file is planned into
/// `<root>/<Kind>/`. Directories are left alone.
pub fn plan_organise_by_kind(root: &str, entries: &[Entry]) -> Plan {
    let mut moves = Vec::new();
    for e in entries {
        if e.is_dir {
            continue;
        }
        let kind = match e.kind {
            Kind::Image => "images",
            Kind::Video => "videos",
            Kind::Audio => "audio",
            Kind::Document => "documents",
            Kind::Archive => "archives",
            Kind::Code => "code",
            _ => "other",
        };
        let dst = format!("{}/{}/{}", root.trim_end_matches('/'), kind, e.name);
        let src = e.loc.path.clone();
        if src != dst {
            moves.push(PlanMove { src, dst });
        }
    }
    Plan { title: "Organise by kind".into(), moves, approved: false }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{Location, SortKey};

    fn entry(name: &str, kind: Kind, is_dir: bool) -> Entry {
        Entry {
            loc: Location::new("local", &format!("/{name}")),
            name: name.to_string(),
            kind,
            is_dir,
            size: 10,
            modified: 0,
            accessed: 0,
            created: 0,
            symlink: false,
            readonly: false,
            executable: false,
            hidden: false,
            mount: false,
        }
    }

    #[test]
    fn organise_plans_by_kind_and_skips_dirs() {
        let entries = vec![
            entry("a.jpg", Kind::Image, false),
            entry("b.mp4", Kind::Video, false),
            entry("docs", Kind::Folder, true),
        ];
        let plan = plan_organise_by_kind("/", &entries);
        assert_eq!(plan.len(), 2);
        assert!(!plan.approved);
        assert!(!plan.is_empty());
        let _ = SortKey::Name; // keep the import pinned for readers
    }

    #[test]
    fn empty_plan() {
        let plan = plan_organise_by_kind("/", &[]);
        assert!(plan.is_empty());
    }
}

//! Host snapshot (the recreate `sys` pattern, ported).
//!
//! A small honest readout of the machine: CPU count, OS, and memory.
//! Used by Settings → About and `diagnostics()`; never faked.

/// Point-in-time host facts.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SysSnapshot {
    pub os: String,
    pub cpus: usize,
    pub mem_total_mb: u64,
}

/// Take a host snapshot. Wasm reports zeros honestly (no sysinfo there).
pub fn host_snapshot() -> SysSnapshot {
    #[cfg(target_arch = "wasm32")]
    {
        return SysSnapshot { os: "wasm".into(), cpus: 0, mem_total_mb: 0 };
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        let cpus = std::thread::available_parallelism().map(|n| n.get()).unwrap_or(0);
        let mem_mb = sysinfo::System::new().total_memory() / (1024 * 1024);
        #[allow(unused_mut)]
        let mut s = SysSnapshot {
            os: std::env::consts::OS.to_string(),
            cpus,
            mem_total_mb: mem_mb,
        };
        if s.os.is_empty() {
            s.os = "unknown".into();
        }
        s
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_is_honest() {
        let s = host_snapshot();
        #[cfg(not(target_arch = "wasm32"))]
        {
            assert!(!s.os.is_empty());
            assert!(s.cpus >= 1);
            assert!(s.mem_total_mb > 0);
        }
        #[cfg(target_arch = "wasm32")]
        {
            assert_eq!(s.os, "wasm");
        }
    }
}

//! Store adapter (the recreate `store`/`engine` pattern, adapted).
//!
//! Recreate's `store`/`engine` cannot be copied verbatim — they depend on
//! recreate's own VFS types, which differ from `Vfs`/`Registry` here. This
//! module ports the *pattern* (one engine fronts every filesystem) as a
//! thin adapter over the existing [`crate::ops::Registry`]: [`Store`] is
//! the engine surface, [`Store::from_registry`] wraps the registry, and the
//! backend (`crate::backend::Backend`) is the concrete store. No behaviour
//! is duplicated — this pins the seam the recreate branch invented.

use crate::model::Location;
use crate::ops::Registry;
use crate::vfs::Vfs;
use std::sync::Arc;

/// One engine fronting every filesystem.
pub struct Store {
    reg: Arc<Registry>,
}

impl Store {
    pub fn from_registry(reg: Arc<Registry>) -> Self {
        Self { reg }
    }

    /// The VFS for `loc`'s filesystem, if registered.
    pub fn vfs(&self, loc: &Location) -> Option<Arc<dyn Vfs>> {
        self.reg.get(&loc.fs)
    }

    /// Filesystems currently registered (adapter: never a third list).
    pub fn filesystems(&self) -> Vec<String> {
        self.reg.list()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::vfs::VfsKind;

    #[test]
    fn adapter_wraps_registry() {
        let mut reg = Registry::new();
        reg.insert(Arc::new(crate::local::LocalVfs));
        let store = Store::from_registry(Arc::new(reg));
        assert!(store.filesystems().contains(&"local".to_string()));
        assert!(store.vfs(&Location::new("local", "/tmp")).is_some());
        assert!(store.vfs(&Location::new("ghost", "/tmp")).is_none());
        let _ = VfsKind::Local;
    }
}

