//! Treemap drawing (UI half of the `squarify` port).
//!
//! Layout is pure and lives in `smart_core::treemap::layout`; this module
//! only knows how to paint the resulting rects. The storage **Map** view
//! calls [`paint_map`]; the **Graph** view calls [`paint_graph`] with the
//! same nodes (obsidian graph: folders as glowing nodes + links).

use crate::theme::{Color32, hex};
use egui::{pos2, Rect};

/// Palette for treemap tiles (category colours, charts-only).
pub fn tile_color(i: usize, dark: bool) -> Color32 {
    let light = [
        hex("#4a86f5"), hex("#57c79a"), hex("#f7c04a"), hex("#e0457b"),
        hex("#8a7cf5"), hex("#f58a4a"), hex("#4ac8c0"), hex("#9aa7bd"),
        hex("#6f9bff"), hex("#59c79a"), hex("#e5b05a"), hex("#ff7a84"),
    ];
    let dark = [
        hex("#86acff"), hex("#59c79a"), hex("#e5b05a"), hex("#ff7a84"),
        hex("#a79bff"), hex("#f5a05a"), hex("#6fd8d0"), hex("#b8c4da"),
        hex("#86acff"), hex("#59c79a"), hex("#e5b05a"), hex("#ff7a84"),
    ];
    if dark { dark[i % 12] } else { light[i % 12] }
}

/// Paint treemap rects (from `smart_core::treemap::layout`) into `bounds`.
pub fn paint_map(p: &egui::Painter, bounds: Rect, rects: &[(String, smart_core::treemap::TreemapRect)]) {
    for (i, (_, r)) in rects.iter().enumerate() {
        let rect = Rect::from_min_size(pos2(bounds.min.x + r.x, bounds.min.y + r.y), egui::vec2(r.w, r.h));
        if rect.width() < 2.0 || rect.height() < 2.0 {
            continue;
        }
        crate::paint::grad_fill(p, rect, 6.0, tile_color(i, false), crate::theme::mix(tile_color(i, false), Color32::BLACK, 0.18));
        p.rect_stroke(rect.shrink(0.5), crate::paint::cr(6.0), egui::Stroke::new(1.0, Color32::WHITE), egui::StrokeKind::Inside);
        let _ = i;
    }
}

/// Paint an obsidian graph: nodes on a deterministic ring around `center`,
/// sized by bytes, linked to the centre. Visual only — no simulation needed
/// for a storage overview (nodes are stable, links do not jitter).
pub fn paint_graph(p: &egui::Painter, center: egui::Pos2, radius: f32, nodes: &[(String, u64)], dark: bool) {
    let max = nodes.iter().map(|(_, b)| *b).max().unwrap_or(1).max(1);
    let n = nodes.len().max(1) as f32;
    for (i, (_, bytes)) in nodes.iter().enumerate() {
        let frac = *bytes as f32 / max as f32;
        let ang = (i as f32 / n) * std::f32::consts::TAU - std::f32::consts::FRAC_PI_2;
        let pos = center + egui::vec2(ang.cos(), ang.sin()) * radius;
        let col = tile_color(i, dark);
        p.line_segment([center, pos], egui::Stroke::new(1.0, crate::theme::alpha(col, 0.35)));
        let r = 7.0 + 14.0 * frac;
        p.circle_filled(pos, r, crate::theme::alpha(col, 0.9));
        p.circle_stroke(pos, r, egui::Stroke::new(1.5, Color32::WHITE));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn palette_is_stable() {
        assert_eq!(tile_color(0, false), tile_color(12, false));
        assert_eq!(tile_color(1, true), tile_color(13, true));
    }
}

//! Storage component (canonical — the ONE storage view every app shares).
//!
//! Ports the eiga storage screen (Overview / Cleanup / Map / Graph / Biggest)
//! into framework components:
//!
//! - **Donut**: used/free pie with the `usage_color` ramp (92%+ reddish).
//! - **Category bars**: per-kind byte bars.
//! - **Biggest wins**: largest files with a Safe/Review verdict per row
//!   (`smart_core::analyze`).
//! - **Map**: squarified treemap (`smart_core::treemap`).
//! - **Graph**: obsidian node graph (same nodes, no simulation).
//!
//! The scan itself stays incremental (`Scan::step(6)` per frame) so the UI
//! never blocks — this component only *paints* what the scan produced.

use crate::treemap;
use crate::theme::{T_META, WinThemeInline as _};
use egui::{pos2, Align2, Color32, Key, Painter, Vec2};

// Re-export the ramp so hosts never hard-code storage colours.
pub use smart_core::scan::usage_color;

/// Which storage view is showing.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum StorageView {
    #[default]
    Overview,
    Cleanup,
    Map,
    Graph,
    Biggest,
}

impl StorageView {
    pub fn all() -> [StorageView; 5] {
        [StorageView::Overview, StorageView::Cleanup, StorageView::Map, StorageView::Graph, StorageView::Biggest]
    }

    pub fn label(self) -> &'static str {
        match self {
            StorageView::Overview => "Overview",
            StorageView::Cleanup => "Cleanup",
            StorageView::Map => "Map",
            StorageView::Graph => "Graph",
            StorageView::Biggest => "Biggest",
        }
    }
}

/// Donut segments: `(label, bytes)`.
pub fn donut_segments(categories: &[(String, u64)]) -> Vec<(String, u64)> {
    categories.to_vec()
}

/// Paint the donut: ring segments proportional to bytes, centre label in
/// `centre_text`. Colours come from the treemap palette; the outer ring
/// colour is `usage_color(frac)` so a nearly-full disk reads reddish.
pub fn paint_donut(p: &Painter, centre: egui::Pos2, radius: f32, segments: &[(String, u64)], frac_used: f32, centre_text: &str, dark: bool) {
    let total: u64 = segments.iter().map(|(_, b)| *b).sum();
    let steps = 64;
    let mut start = -std::f32::consts::FRAC_PI_2;
    if total == 0 {
        // Empty: single ring in well colour.
        crate::paint::grad_fill(p, egui::Rect::from_center_size(centre, egui::vec2(radius * 2.0, radius * 2.0)), 0.0, Color32::LIGHT_GRAY, Color32::LIGHT_GRAY);
        let _ = steps;
    } else {
        for (i, (_, bytes)) in segments.iter().enumerate() {
            let sweep = (*bytes as f32 / total as f32) * std::f32::consts::TAU;
            let col = treemap::tile_color(i, dark);
            donut_segment(p, centre, radius, start, sweep, col);
            start += sweep;
        }
    }
    // Outer usage ring (the alarm).
    let (r, g, b) = usage_color(frac_used);
    p.circle_stroke(centre, radius + 3.0, egui::Stroke::new(3.0, Color32::from_rgb(r, g, b)));
    if !centre_text.is_empty() {
        p.text(centre, Align2::CENTER_CENTER, centre_text, crate::theme::f_bold(T_META + 2.0), Color32::WHITE);
    }
}

/// One ring segment as a fan mesh (`start`/`sweep` in radians).
fn donut_segment(p: &Painter, centre: egui::Pos2, radius: f32, start: f32, sweep: f32, col: Color32) {
    if sweep <= 0.0 {
        return;
    }
    let n = (sweep / 0.08).ceil().clamp(2.0, 80.0) as usize;
    let inner = radius * 0.62;
    let mut verts = Vec::with_capacity(n * 2 + 2);
    for i in 0..=n {
        let a = start + sweep * (i as f32 / n as f32);
        verts.push((centre + egui::vec2(a.cos(), a.sin()) * radius, col));
    }
    for i in 0..=n {
        let a = start + sweep * (i as f32 / n as f32);
        verts.push((centre + egui::vec2(a.cos(), a.sin()) * inner, col));
    }
    let mut mesh = crate::theme::Mesh::default();
    for (pt, c) in &verts {
        mesh.vertices.push(egui::epaint::Vertex { pos: *pt, uv: egui::epaint::WHITE_UV, color: *c });
    }
    let top = (n + 1) as u32;
    for i in 0..n as u32 {
        mesh.indices.extend([i, i + 1, top + i, i + 1, top + i + 1, top + i]);
    }
    p.add(egui::Shape::mesh(mesh));
}

/// Category bar rows: `(label, bytes)` → painted as proportional bars.
pub fn category_bars(p: &Painter, origin: egui::Pos2, width: f32, categories: &[(String, u64)], dark: bool, row_h: f32) {
    let max = categories.iter().map(|(_, b)| *b).max().unwrap_or(1).max(1) as f32;
    for (i, (label, bytes)) in categories.iter().enumerate() {
        let y = origin.y + i as f32 * row_h;
        let frac = *bytes as f32 / max;
        let col = treemap::tile_color(i, dark);
        let bar = egui::Rect::from_min_size(pos2(origin.x + 110.0, y), egui::vec2((width - 110.0) * frac, row_h - 10.0));
        p.rect_filled(bar, crate::paint::cr(4.0), col);
        p.text(pos2(origin.x, y + (row_h - 10.0) / 2.0), Align2::LEFT_CENTER, label.clone(), crate::theme::f_medium(T_META), if dark { Color32::WHITE } else { Color32::BLACK });
    }
}

/// Obsidian graph paint (delegates to the treemap module).
pub fn paint_graph(p: &Painter, centre: egui::Pos2, radius: f32, nodes: &[(String, u64)], dark: bool) {
    treemap::paint_graph(p, centre, radius, nodes, dark);
}

/// Map paint (delegates to the treemap module).
pub fn paint_map(p: &Painter, bounds: egui::Rect, rects: &[(String, smart_core::treemap::TreemapRect)]) {
    treemap::paint_map(p, bounds, rects);
}

/// Biggest-wins rows from `(path, bytes)`: Safe/Review verdicts attached.
pub fn biggest_wins(rows: &[(String, u64)]) -> Vec<smart_core::analyze::BiggestWin> {
    smart_core::analyze::biggest_wins(rows)
}

// Helper trait alias so `crate::theme::Mesh` reads naturally.
mod _alias {
    pub trait WinThemeInline {
        fn mesh() -> ();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn views_are_named() {
        assert_eq!(StorageView::all().len(), 5);
        assert_eq!(StorageView::Map.label(), "Map");
        assert_eq!(StorageView::Biggest.label(), "Biggest");
    }

    #[test]
    fn ramp_is_the_alarm() {
        assert_eq!(usage_color(0.92), (224, 69, 123));
        assert_eq!(usage_color(0.2), (87, 199, 154));
    }

    #[test]
    fn biggest_wins_delegate() {
        let rows = vec![("/a.tmp".to_string(), 100u64), ("/v.mp4".to_string(), 500 << 20)];
        let wins = biggest_wins(&rows);
        assert_eq!(wins.len(), 2);
        assert!(wins.iter().all(|w| w.verdict != smart_core::analyze::Verdict::Keep));
    }

    #[test]
    fn donut_segments_preserve() {
        let segs = donut_segments(&[("img".into(), 10u64), ("vid".into(), 20u64)]);
        assert_eq!(segs.len(), 2);
    }
}

