/// File chooser (canonical picker): New Folder, live search, multi-sort.
/// Lists the current folder (`self.items`); ticking an item adds it to
/// `picker.selection`; Choose navigates (dirs) or closes with the first
/// selected non-dir. XDG portal: when `picker::portal_available()` the
/// host may use the native portal instead — this sheet is the fallback.
fn m_picker(&mut self, ui: &mut Ui, card: Rect, close: &mut bool) {
    let p = ui.painter().clone();
    let th = self.th.clone();
    if self.modal_head(ui, card, "folder", "Choose a file or folder", "Search to filter · multi-select ticks · dirs navigate", true) {
        *close = true;
    }
    let body = Rect::from_min_max(card.min + vec2(20.0, 78.0), pos2(card.right() - 20.0, card.bottom() - 66.0));
    // Search row.
    let search = Rect::from_min_size(pos2(body.left(), body.top()), vec2(body.width() - 140.0, 34.0));
    let mut q = std::mem::take(&mut self.picker.query);
    let out = ui.new_child(egui::UiBuilder::new().max_rect(search).layout(egui::Layout::top_down(egui::Align::Min)))
        .add(egui::TextEdit::singleline(&mut q).id(Id::new("picker-search")).hint_text("Search…"));
    if out.changed() {
        self.picker.query = q;
    } else {
        self.picker.query = q;
    }
    // Sort buttons (Name/Size/Date) + New Folder.
    let mut bx = body.left();
    for sort in [crate::picker::PickerSort::Name, crate::picker::PickerSort::Size, crate::picker::PickerSort::Date] {
        let label = sort.label();
        let w = self.tw(&p, label, &f_semi(11.0)) + 22.0;
        let b = Rect::from_min_size(pos2(bx, body.top() + 42.0), vec2(w, 30.0));
        bx += w + 6.0;
        let kindb = if self.picker.sort == sort { Btn::Accent } else { Btn::Raised };
        if self.label_button(ui, b, None, label, &format!("pk-sort-{}", label), kindb).clicked() {
            self.picker.sort = sort;
        }
    }
    let nf = Rect::from_min_size(pos2(body.right() - 120.0, body.top() + 42.0), vec2(120.0, 30.0));
    if self.label_button(ui, nf, Some("folder"), "New Folder", "pk-newfolder", Btn::Raised).clicked() {
        self.acts.push(Act::NewFolder);
    }
    // List.
    let list = Rect::from_min_max(pos2(body.left(), body.top() + 82.0), pos2(body.right(), body.bottom()));
    let mut names: Vec<String> = self.items.iter().map(|e| e.name.clone()).collect();
    let q = self.picker.query.trim().to_lowercase();
    if !q.is_empty() {
        names.retain(|n| n.to_lowercase().contains(&q));
    }
    match self.picker.sort {
        crate::picker::PickerSort::Name => names.sort(),
        crate::picker::PickerSort::Size => names.sort_by_key(|n| self.items.iter().find(|e| &e.name == n).map(|e| e.size).unwrap_or(0)),
        crate::picker::PickerSort::Date => names.sort_by_key(|n| self.items.iter().find(|e| &e.name == n).and_then(|e| e.modified).unwrap_or(0)),
        crate::picker::PickerSort::Kind => names.sort_by_key(|n| self.items.iter().find(|e| &e.name == n).map(|e| e.kind as u8).unwrap_or(9)),
    }
    let mut lui = ui.new_child(egui::UiBuilder::new().max_rect(list).layout(egui::Layout::top_down(egui::Align::Min)));
    lui.set_clip_rect(list.intersect(ui.clip_rect()));
    egui::ScrollArea::vertical().id_salt("picker-list").auto_shrink([false, false]).show(&mut lui, |ui| {
        let top = ui.max_rect().top();
        let row_h = 34.0;
        ui.allocate_rect(Rect::from_min_size(pos2(list.left(), top), vec2(list.width(), names.len() as f32 * row_h + 20.0)), Sense::hover());
        for (i, name) in names.iter().enumerate() {
            let r = Rect::from_min_size(pos2(list.left(), top + i as f32 * row_h), vec2(list.width(), row_h - 4.0));
            let entry = self.items.iter().find(|e| &e.name == name).cloned();
            let Some(e) = entry else { continue };
            let is_sel = self.picker.selection.iter().any(|s| s == &e.loc.path);
            if is_sel {
                p.rect_filled(r, cratesmart_cr(8.0), crate::theme::alpha(th.accent, 0.14));
            }
            self.tick_badge(ui, r, is_sel, &format!("pk-{i}"));
            self.ico(&p, e.kind.icon(), Ic::Duo, pos2(r.left() + 44.0, r.center().y), 15.0, th.accent);
            p.text(pos2(r.left() + 64.0, r.center().y), Align2::LEFT_CENTER, self.fit(&p, &e.name, &f_medium(T_BODY), r.width() - 180.0), f_medium(T_BODY), if is_sel { th.accent_ink } else { th.ink1 });
            let hit = self.hit(ui, r, ("pk-row", &e.loc.path), Sense::click());
            if hit.clicked() {
                if e.is_dir {
                    self.acts.push(Act::Nav(Route::Loc(e.loc.clone())));
                } else {
                    if let Some(pos) = self.picker.selection.iter().position(|s| s == &e.loc.path) {
                        self.picker.selection.remove(pos);
                    } else {
                        self.picker.selection.push(e.loc.path.clone());
                    }
                }
            }
        }
    });
    // Footer: count + Choose/ Cancel.
    let n = self.picker.selection.len();
    p.text(pos2(card.left() + 20.0, card.bottom() - 32.0), Align2::LEFT_CENTER, format!("{n} selected"), f_medium(T_META), th.ink3);
    let mut cur = card.right() - 20.0;
    if self.foot_btn(ui, card, &mut cur, "Choose", Btn::Accent, "pk-choose") {
        if let Some(first) = self.picker.selection.first().cloned() {
            let loc = Location::new(self.current_loc().map(|l| l.fs.clone()).unwrap_or_else(|| "local".into()), &first);
            self.acts.push(Act::Open(loc));
        }
        *close = true;
    }
    if self.foot_btn(ui, card, &mut cur, "Cancel", Btn::Raised, "pk-cancel") {
        *close = true;
    }
}

