/// "Computer X free of Y" status line (same as Files). Best-effort via
/// `df --output=avail,size /`; honestly reports "free space unavailable"
/// when `df` is missing (never a fake number).
pub fn computer_free_line() -> String {
    #[cfg(not(target_arch = "wasm32"))]
    {
        if let Ok(out) = std::process::Command::new("df").args(["--output=avail,size", "/"]).output() {
            if out.status.success() {
                let s = String::from_utf8_lossy(&out.stdout);
                let mut it = s.lines().skip(1);
                let avail = it.next().and_then(|l| l.split_whitespace().next()).unwrap_or("");
                let size = s.lines().skip(1).filter_map(|l| l.split_whitespace().nth(1)).next().unwrap_or("");
                if !avail.is_empty() && !size.is_empty() {
                    let gb = |kb: &str| -> String {
                        kb.parse::<u64>().map(|v| format!("{:.1}GB", v as f64 / (1024.0 * 1024.0))).unwrap_or_else(|_| format!("{kb}K"))
                    };
                    return format!("Computer {} free of {}", gb(avail), gb(size));
                }
            }
        }
        "Computer free space unavailable".to_string()
    }
    #[cfg(target_arch = "wasm32")]
    {
        "Computer free space unavailable".to_string()
    }
}

