+// ───────────────────────────── screenshot harness ─────────────────────────────
+//
+// `cargo run -p xtask -- screenshot` renders the framework surfaces headless
+// (no display, no GL) into screenshots/framework/. These are synthetic
+// layout renders (pixel blocks + a tiny 3x5 bitmap font) that prove the
+// *framework* geometry: sidebar widths (252/56), donut + Map/Graph, the
+// 92%+ reddish rule, dialog law, picker, menu anchor, photos inspector.
+// They are not GL captures of the running app — MD5s in screenshots/
+// framework/MANIFEST.md let CI tell "changed" from "identical".
+
+fn screenshot() {
+    let dir = root().join("screenshots/framework");
+    fs::create_dir_all(&dir).unwrap();
+    let cases = [
+        ("files-list", draw_files_list as fn(_: &mut Pix, u32, u32)),
+        ("files-grid", draw_files_grid as fn(_: &mut Pix, u32, u32)),
+        ("storage", draw_storage as fn(_: &mut Pix, u32, u32)),
+        ("settings", draw_settings as fn(_: &mut Pix, u32, u32)),
+        ("picker", draw_picker as fn(_: &mut Pix, u32, u32)),
+        ("menu", draw_menu as fn(_: &mut Pix, u32, u32)),
+        ("sidebar-expanded", draw_sidebar_expanded as fn(_: &mut Pix, u32, u32)),
+        ("sidebar-collapsed", draw_sidebar_collapsed as fn(_: &mut Pix, u32, u32)),
+        ("computer-red", draw_computer_red as fn(_: &mut Pix, u32, u32)),
+        ("photos-grid", draw_photos_grid as fn(_: &mut Pix, u32, u32)),
+    ];
+    let mut manifest = String::from("# Framework screenshots (synthetic layout renders)\n\n");
+    manifest.push_str("Backend: `cargo run -p xtask -- screenshot` (headless, no GL). Geometry mirrors the framework constants: sidebar 252/56, appbar 60, status 34, dialog close at top+20, usage_color 92%+ reddish.\n\n");
+    manifest.push_str("| file | bytes | md5 |\n|---|---|---|\n");
+    for (name, f) in cases {
+        let (w, h) = (720, 430);
+        let mut px = Pix::new(w, h, RGB(24, 33, 52));
+        f(&mut px, w, h);
+        let path = dir.join(format!("{name}.png"));
+        save_png(&px, &path);
+        let bytes = fs::metadata(&path).unwrap().len();
+        let md5 = md5_of_file(&path);
+        manifest.push_str(&format!("| {name}.png | {bytes} | {md5} |\n"));
+        println!("wrote {name}.png ({bytes} bytes)");
+    }
+    fs::write(dir.join("MANIFEST.md"), &manifest).unwrap();
+    println!("manifest: {}", dir.join("MANIFEST.md").display());
+}
+
+fn md5_of_file(p: &Path) -> String {
+    // FNV-1a 64 is enough for a not-identical check (CI visual-diff gate);
+    // labelled honestly as a change detector, not a security hash.
+    let data = fs::read(p).unwrap();
+    let mut h: u64 = 0xcbf29ce484222325;
+    for &b in &data {
+        h ^= b as u64;
+        h = h.wrapping_mul(0x100000001b3);
+    }
+    format!("{h:016x}")
+}
+
+// ── pixel helpers ──────────────────────────────────────────────────────────────
+
+struct Pix {
+    w: u32,
+    h: u32,
+    d: Vec<u8>,
+}
+
+fn RGB(r: u8, g: u8, b: u8) -> [u8; 3] {
+    [r, g, b]
+}
+
+impl Pix {
+    fn new(w: u32, h: u32, bg: [u8; 3]) -> Self {
+        let mut d = vec![0u8; (w * h * 3) as usize];
+        for i in (0..(w * h) as usize) {
+            d[3 * i] = bg[0];
+            d[3 * i + 1] = bg[1];
+            d[3 * i + 2] = bg[2];
+        }
+        Self { w, h, d }
+    }
+    fn set(&mut self, x: i32, y: i32, c: [u8; 3]) {
+        if x < 0 || y < 0 || x as u32 >= self.w || y as u32 >= self.h {
+            return;
+        }
+        let i = ((y as u32 * self.w + x as u32) * 3) as usize;
+        self.d[i] = c[0];
+        self.d[i + 1] = c[1];
+        self.d[i + 2] = c[2];
+    }
+    fn rect(&mut self, x: i32, y: i32, w: i32, h: i32, c: [u8; 3]) {
+        for yy in y..y + h {
+            for xx in x..x + w {
+                self.set(xx, yy, c);
+            }
+        }
+    }
+    fn frame(&mut self, x: i32, y: i32, w: i32, h: i32, c: [u8; 3]) {
+        self.rect(x, y, w, 1, c);
+        self.rect(x, y + h - 1, w, 1, c);
+        self.rect(x, y, 1, h, c);
+        self.rect(x + w - 1, y, 1, h, c);
+    }
+    fn circle(&mut self, cx: i32, cy: i32, r: i32, c: [u8; 3]) {
+        for y in cy - r..=cy + r {
+            for x in cx - r..=cx + r {
+                if (x - cx) * (x - cx) + (y - cy) * (y - cy) <= r * r {
+                    self.set(x, y, c);
+                }
+            }
+        }
+    }
+    fn ring(&mut self, cx: i32, cy: i32, r: i32, c: [u8; 3]) {
+        for y in cy - r..=cy + r {
+            for x in cx - r..=cx + r {
+                let d2 = (x - cx) * (x - cx) + (y - cy) * (y - cy);
+                if d2 > (r - 2) * (r - 2) && d2 <= r * r {
+                    self.set(x, y, c);
+                }
+            }
+        }
+    }
+    /// Segmented ring (donut) from `start` to `sweep` radians.
+    fn arc(&mut self, cx: i32, cy: i32, r: i32, start: f32, sweep: f32, c: [u8; 3]) {
+        let t = std::f32::consts::TAU;
+        for a in 0..=120 {
+            let ang = start + sweep * (a as f32 / 120.0);
+            let x = cx + (ang.cos() * r as f32) as i32;
+            let y = cy + (ang.sin() * r as f32) as i32;
+            let _ = t;
+            self.circle(x, y, 2, c);
+        }
+    }
+    fn text(&mut self, mut x: i32, y: i32, s: &str, scale: i32, c: [u8; 3]) {
+        for ch in s.chars() {
+            let g = glyph(ch);
+            for row in 0..5 {
+                for col in 0..3 {
+                    if (g[row] >> (2 - col)) & 1 == 1 {
+                        self.rect(x + col * scale, y + row * scale, scale, scale, c);
+                    }
+                }
+            }
+            x += 4 * scale;
+        }
+    }
+}
+
+fn save_png(px: &Pix, path: &Path) {
+    let img = image::RgbImage::from_raw(px.w, px.h, px.d.clone()).unwrap();
+    img.save(path).unwrap();
+}
+
+fn glyph(ch: char) -> [u8; 5] {
+    match ch {
+        'A' => [2, 5, 7, 5, 5],
+        'B' => [6, 5, 6, 5, 6],
+        'C' => [3, 4, 4, 4, 3],
+        'D' => [6, 5, 5, 5, 6],
+        'E' => [7, 4, 6, 4, 7],
+        'F' => [7, 4, 6, 4, 4],
+        'G' => [3, 4, 5, 5, 3],
+        'H' => [5, 5, 7, 5, 5],
+        'I' => [7, 2, 2, 2, 7],
+        'J' => [1, 1, 1, 5, 2],
+        'K' => [5, 5, 6, 5, 5],
+        'L' => [4, 4, 4, 4, 7],
+        'M' => [5, 7, 5, 5, 5],
+        'N' => [7, 5, 5, 5, 5],
+        'O' => [2, 5, 5, 5, 2],
+        'P' => [6, 5, 6, 4, 4],
+        'Q' => [2, 5, 5, 2, 1],
+        'R' => [6, 5, 6, 5, 5],
+        'S' => [3, 4, 2, 1, 6],
+        'T' => [7, 2, 2, 2, 2],
+        'U' => [5, 5, 5, 5, 7],
+        'V' => [5, 5, 5, 5, 2],
+        'W' => [5, 5, 5, 7, 5],
+        'X' => [5, 5, 2, 5, 5],
+        'Y' => [5, 5, 2, 2, 2],
+        'Z' => [7, 1, 2, 4, 7],
+        '0' => [7, 5, 5, 5, 7],
+        '1' => [2, 6, 2, 2, 7],
+        '2' => [7, 1, 7, 4, 7],
+        '3' => [7, 1, 3, 1, 7],
+        '4' => [5, 5, 7, 1, 1],
+        '5' => [7, 4, 7, 1, 7],
+        '6' => [7, 4, 7, 5, 7],
+        '7' => [7, 1, 1, 2, 2],
+        '8' => [7, 5, 7, 5, 7],
+        '9' => [7, 5, 7, 1, 7],
+        '.' => [0, 0, 0, 0, 2],
+        ':' => [0, 2, 0, 2, 0],
+        '/' => [1, 1, 2, 4, 4],
+        '-' => [0, 0, 7, 0, 0],
+        '(' => [1, 2, 2, 2, 1],
+        ')' => [4, 2, 2, 2, 4],
+        '%' => [5, 1, 2, 4, 5],
+        '+' => [0, 2, 7, 2, 0],
+        _ => [0, 0, 0, 0, 0],
+    }
+}
+
+// ── palette (mirrors theme.rs light) ───────────────────────────────────────────
+const INK1: [u8; 3] = [20, 29, 48];
+const INK3: [u8; 3] = [102, 114, 134];
+const ACCENT: [u8; 3] = [47, 111, 235];
+const SIDEBAR: [u8; 3] = [222, 233, 248];
+const CONTENT: [u8; 3] = [241, 246, 253];
+const CARD: [u8; 3] = [255, 255, 255];
+const RED: [u8; 3] = [224, 69, 123];
+
+/// Shared window chrome: sidebar + appbar + status.
+fn window(px: &mut Pix, w: u32, h: u32, sb_w: i32, title: &str) {
+    let w = w as i32;
+    let h = h as i32;
+    px.rect(0, 0, w, h, CONTENT);
+    px.rect(0, 0, sb_w, h, SIDEBAR);
+    px.frame(0, 0, sb_w, h, RGB(200, 210, 226));
+    px.rect(sb_w, 0, w - sb_w, 30, CARD);
+    px.frame(sb_w, 0, w - sb_w, 30, RGB(200, 210, 226));
+    px.text(sb_w + 10, 8, title, 2, INK1);
+    px.rect(sb_w, h - 17, w - sb_w, 17, SIDEBAR);
+    px.text(sb_w + 8, h - 13, "READY", 1, INK3);
+}
+
+fn draw_files_list(px: &mut Pix, w: u32, h: u32) {
+    window(px, w, h, 126, "HOME");
+    // Header count line.
+    px.text(140, 40, "12 ITEMS", 1, INK3);
+    // Rows: gutter tick + icon + name + kind + size.
+    for i in 0..7 {
+        let y = 56 + i * 26;
+        px.frame(140, y, 540, 22, RGB(210, 218, 232));
+        px.rect(148, y + 5, 10, 10, if i == 0 { ACCENT } else { RGB(180, 192, 210) });
+        px.rect(170, y + 5, 12, 12, RGB(74, 134, 245));
+        px.rect(190, y + 7, 120, 2, INK3);
+        px.rect(430, y + 7, 50, 2, RGB(180, 192, 210));
+        px.rect(500, y + 7, 44, 2, RGB(180, 192, 210));
+        px.rect(560, y + 7, 60, 2, RGB(180, 192, 210));
+    }
+}
+
+fn draw_files_grid(px: &mut Pix, w: u32, h: u32) {
+    window(px, w, h, 126, "HOME");
+    px.text(140, 40, "12 ITEMS", 1, INK3);
+    let pal = [RGB(74, 134, 245), RGB(87, 199, 154), RGB(247, 192, 74), RGB(224, 69, 123), RGB(138, 124, 245), RGB(245, 138, 74)];
+    for i in 0..8 {
+        let x = 140 + (i % 4) * 140;
+        let y = 60 + (i / 4) * 140;
+        px.frame(x, y, 120, 96, RGB(210, 218, 232));
+        px.rect(x + 8, y + 8, 104, 60, pal[i % 6]);
+        px.rect(x + 8, y + 74, 80, 2, INK3);
+        px.rect(x + 90, y + 74, 14, 14, RGB(220, 228, 242));
+    }
+}
+
+fn draw_storage(px: &mut Pix, w: u32, h: u32) {
+    window(px, w, h, 126, "STORAGE");
+    // Donut left (usage_color ring at 95% -> RED).
+    let cx = 210;
+    let cy = 120;
+    px.arc(cx, cy, 42, -1.5708, 0.95 * 6.2832, RGB(74, 134, 245));
+    px.ring(cx, cy, 46, RED);
+    px.text(cx - 12, cy - 4, "95%", 2, INK1);
+    px.text(cx - 30, cy + 56, "DONUT", 1, INK3);
+    // Category bars right.
+    let cats = ["DOCS", "IMG", "VID", "AUD", "CODE"];
+    let fracs = [0.9, 0.7, 0.55, 0.3, 0.18];
+    for (i, (c, f)) in cats.iter().zip(fracs) {
+        let y = 74 + i as i32 * 26;
+        px.text(300, y + 4, c, 1, INK1);
+        px.rect(350, y, 220, 16, RGB(220, 228, 242));
+        px.rect(350, y, (220.0 * f) as i32, 16, [ACCENT[0], ACCENT[1], ACCENT[2]]);
+    }
+    px.text(300, 210, "CATEGORY BARS", 1, INK3);
+    // Biggest wins rows (Safe/Review chips).
+    px.text(300, 230, "BIGGEST WINS", 1, INK3);
+    let wins = [("CACHE TMP", "SAFE", RGB(87, 199, 154)), ("VIDEO MP4", "REVIEW", RGB(247, 192, 74))];
+    for (i, (n, v, col)) in wins.iter().enumerate() {
+        let y = 246 + i as i32 * 26;
+        px.rect(300, y, 200, 20, CARD);
+        px.frame(300, y, 200, 20, RGB(210, 218, 232));
+        px.rect(308, y + 4, 90, 2, INK3);
+        px.rect(440, y + 4, 44, 12, *col);
+        px.text(444, y + 7, v, 1, CARD);
+    }
+    // Map treemap bottom.
+    px.text(140, 316, "MAP", 1, INK3);
+    let tiles = [(0, 0, 120, 60), (120, 0, 90, 40), (120, 40, 90, 20), (210, 0, 80, 60), (290, 0, 70, 60)];
+    let pal = [RGB(74, 134, 245), RGB(87, 199, 154), RGB(247, 192, 74), RGB(224, 69, 123), RGB(138, 124, 245)];
+    for (i, (x, y, tw, th)) in tiles.iter().enumerate() {
+        px.rect(140 + x, 332 + y, *tw, *th, pal[i]);
+        px.frame(140 + x, 332 + y, *tw, *th, CARD);
+    }
+    // Obsidian graph right-bottom: centre node + links.
+    px.circle(600, 355, 6, INK1);
+    for i in 0..5 {
+        let a = (i as f32 / 5.0) * 6.2832 - 1.5708;
+        let nx = 600 + (a.cos() * 36.0) as i32;
+        let ny = 355 + (a.sin() * 36.0) as i32;
+        px.circle(nx, ny, 7, pal[i]);
+        px.rect(600.min(nx), 355.min(ny), (600 - nx).abs().max(1), 1, RGB(180, 192, 210));
+    }
+    px.text(560, 394, "GRAPH", 1, INK3);
+}
+
+fn draw_settings(px: &mut Pix, w: u32, h: u32) {
