+        px.frame(x + 16, yy, dw - 32, 22, RGB(210, 218, 232));
+        px.circle(x + 28, yy + 11, 6, if i == 0 { ACCENT } else { RGB(200, 210, 226) });
+        px.rect(x + 44, yy + 8, 150, 2, INK3);
+    }
+    px.text(x + 16, y + dh - 24, "1 SELECTED", 1, INK3);
+    px.rect(x + dw - 160, y + dh - 30, 70, 22, CARD);
+    px.frame(x + dw - 160, y + dh - 30, 70, 22, RGB(210, 218, 232));
+    px.text(x + dw - 150, y + dh - 23, "CANCEL", 1, INK1);
+    px.rect(x + dw - 84, y + dh - 30, 70, 22, ACCENT);
+    px.text(x + dw - 76, y + dh - 23, "CHOOSE", 1, CARD);
+}
+
+fn draw_menu(px: &mut Pix, w: u32, h: u32) {
+    window(px, w, h, 126, "HOME");
+    for i in 0..5 {
+        let y = 60 + i * 26;
